--              email_suppression_list, referral_programs,
--              marketing_waitlist_rules, marketing_templates,
--              bookings attribution FKs, 6 RPCs, booking triggers.
--
-- Rollback:
--   DROP TRIGGER IF EXISTS trg_attribute_booking_on_insert ON bookings;
--   DROP TRIGGER IF EXISTS trg_waitlist_notify_on_cancel ON bookings;
--   DROP FUNCTION IF EXISTS fn_attribute_booking_on_insert() CASCADE;
--   DROP FUNCTION IF EXISTS fn_notify_waitlist_on_cancel() CASCADE;
