-- ─────────────────────────────────────────────────────────────────────────────
-- 0. Guard: ensure handle_updated_at() function exists
--    (created in a prior migration; included here as a safety net)
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. audience_segments — saved filter presets per studio
--    RLS: studio members read; owner/admin/manager write.
--    Audit trigger: yes (mutations are user-intent, worth logging).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.audience_segments (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id   uuid        NOT NULL REFERENCES public.studios(id)     ON DELETE CASCADE,
  name        text        NOT NULL,
  -- Shape: { groups: [{ op: "AND"|"OR", conditions: [...] }], exclude: [...] }
  filter      jsonb       NOT NULL DEFAULT '{}'::jsonb,
  created_by  uuid        REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_audience_segments_studio_name UNIQUE (studio_id, name)
);

COMMENT ON TABLE  public.audience_segments                   IS 'Saved audience filter presets per studio.';
COMMENT ON COLUMN public.audience_segments.filter            IS 'JSONB shape: { groups: [{ op: AND|OR, conditions: [...] }], exclude: [...] }';
COMMENT ON COLUMN public.audience_segments.created_by        IS 'PII:L2 — user_id of creator';

ALTER TABLE public.audience_segments ENABLE ROW LEVEL SECURITY;

-- Members of the studio can read all segments
CREATE POLICY "audience_segments_select" ON public.audience_segments
  FOR SELECT USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members WHERE user_id = auth.uid()
    )
  );

-- Owner / admin / manager can insert
CREATE POLICY "audience_segments_insert" ON public.audience_segments
  FOR INSERT WITH CHECK (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  );

-- Owner / admin / manager can update
CREATE POLICY "audience_segments_update" ON public.audience_segments
  FOR UPDATE USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  )
  WITH CHECK (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  );

-- Owner / admin / manager can delete
CREATE POLICY "audience_segments_delete" ON public.audience_segments
  FOR DELETE USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  );

-- Indexes
CREATE INDEX IF NOT EXISTS idx_audience_segments_studio_id   ON public.audience_segments(studio_id);
CREATE INDEX IF NOT EXISTS idx_audience_segments_created_by  ON public.audience_segments(created_by);

-- updated_at trigger
DROP TRIGGER IF EXISTS set_audience_segments_updated_at ON public.audience_segments;
CREATE TRIGGER set_audience_segments_updated_at
  BEFORE UPDATE ON public.audience_segments
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

-- Audit trigger (reuses fn_inventory_audit pattern — generic direct INSERT into audit_log)
CREATE OR REPLACE FUNCTION fn_audience_segments_audit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row     jsonb;
  v_old_row jsonb;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN COALESCE(NEW, OLD); END IF;
  IF    TG_OP = 'DELETE' THEN v_row := row_to_json(OLD)::jsonb; v_old_row := v_row;
  ELSIF TG_OP = 'INSERT' THEN v_row := row_to_json(NEW)::jsonb; v_old_row := NULL;
  ELSE                         v_row := row_to_json(NEW)::jsonb; v_old_row := row_to_json(OLD)::jsonb;
  END IF;
  INSERT INTO audit_log (action, actor_id, studio_id, target_type, target_id, details, created_at)
  VALUES (
    'audience_segments.' || lower(TG_OP),
    auth.uid(),
    (v_row->>'studio_id')::uuid,
    'audience_segments',
    v_row->>'id',
    CASE TG_OP
      WHEN 'INSERT' THEN jsonb_build_object('new', v_row)
      WHEN 'UPDATE' THEN jsonb_build_object('old', v_old_row, 'new', v_row)
      WHEN 'DELETE' THEN jsonb_build_object('old', v_row)
    END,

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import type { SupabaseClient } from '@supabase/supabase-js'

// ─────────────────────────────────────────────────────────────────────────────
// Shared RPC helper for segment counts
// ─────────────────────────────────────────────────────────────────────────────

interface SegmentCounts {
  all: number
  inactive_90d: number
  new_30d: number
  top_spenders: number
  birthday_month: number
  booked_next_14d: number
  unsubscribed: number
}

async function callSegmentCountsRpc(
  supabase: SupabaseClient,
  studioId: string
): Promise<{ data: SegmentCounts | null; error: Error | null }> {
  const client = supabase as unknown as {
    rpc: (fn: string, args: Record<string, string>) => Promise<{
      data: SegmentCounts | null
      error: { message: string } | null
    }>
  }
  const result = await client.rpc('get_marketing_segment_counts', { p_studio_id: studioId })
  return {
    data: result.data,
    error: result.error ? new Error(result.error.message) : null,
  }
}

const EMPTY_COUNTS: SegmentCounts = {
  all: 0,
  inactive_90d: 0,
  new_30d: 0,
  top_spenders: 0,
  birthday_month: 0,
  booked_next_14d: 0,
  unsubscribed: 0,
}

// ─────────────────────────────────────────────────────────────────────────────
// audience_segments table helper (M6 migration — cast until db:types re-run)
// ─────────────────────────────────────────────────────────────────────────────

interface SegmentInsert {
  studio_id: string
  name: string
  filter: Record<string, unknown>
  created_by: string
}

interface SegmentResult {
  id: string
  name: string
}

async function insertAudienceSegment(
  supabase: SupabaseClient,
  values: SegmentInsert,
): Promise<{ data: SegmentResult | null; error: Error | null }> {
  const client = supabase as unknown as {
    from: (table: string) => {
      insert: (row: SegmentInsert) => {
        select: (cols: string) => {
          single: () => Promise<{
            data: SegmentResult | null
            error: { message: string } | null
          }>
        }
      }
    }
  }
  const result = await client
    .from('audience_segments')
    .insert(values)
    .select('id, name')
    .single()
  return {
    data: result.data,
    error: result.error ? new Error(result.error.message) : null,
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET — segment preset counts
// ─────────────────────────────────────────────────────────────────────────────

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const { data, error } = await callSegmentCountsRpc(supabase, authUser.studioId)

    if (error) {
      logger.warn({ err: error, studioId: authUser.studioId }, 'segment counts rpc failed — returning empty counts')
      return NextResponse.json({ data: EMPTY_COUNTS })
    }

    return NextResponse.json({ data: data ?? EMPTY_COUNTS })
  } catch (err) {
    logger.error({ err }, 'segment counts unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST — create a saved audience segment
// ─────────────────────────────────────────────────────────────────────────────

const CreateSegmentSchema = z.object({
  name: z.string().min(1, 'Name is required').max(120),
  filter: z.record(z.unknown()),
})

export async function POST(request: Request) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateSegmentSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Invalid input' }, { status: 422 })
  }

  const { name, filter } = parsed.data

  try {
    const supabase = await createClient()
    const { data, error } = await insertAudienceSegment(supabase, {
      studio_id: authUser.studioId,
      name,
      filter,
      created_by: authUser.user.id,
    })

    if (error || !data) {
      logger.warn({ err: error, studioId: authUser.studioId }, 'audience_segments insert failed')
      return NextResponse.json({ error: 'Could not save segment. Database migration may be pending.' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'audience_segment.created',
      { type: 'audience_segment', id: data.id },
      { name, filter: filter as unknown as import('@/lib/supabase/types').Json },
      authUser.studioId,
    )

    return NextResponse.json({ id: data.id, name: data.name }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'audience segment create unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
