import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import type { SupabaseClient } from '@supabase/supabase-js'

interface RouteContext {
  params: Promise<{ id: string }>
}

interface SegmentRow {
  id: string
  name: string
  filter: Record<string, unknown>
  created_at: string
}

// audience_segments is created in the M6 migration — cast until pnpm db:types re-run
function makeAudienceSegmentsClient(supabase: SupabaseClient) {
  return supabase as unknown as {
    from: (table: 'audience_segments') => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          single: () => Promise<{ data: SegmentRow | null; error: { message: string } | null }>
          // chained eq
          eq: (col: string, val: string) => {
            single: () => Promise<{ data: SegmentRow | null; error: { message: string } | null }>
          }
        }
      }
      delete: () => {
        eq: (col: string, val: string) => {
          eq: (col: string, val: string) => Promise<{ error: { message: string } | null }>
        }
      }
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET — fetch a single saved segment
// ─────────────────────────────────────────────────────────────────────────────

export async function GET(_request: Request, context: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await context.params

  try {
    const supabase = await createClient()
    const client = makeAudienceSegmentsClient(supabase)

    const { data, error } = await client
      .from('audience_segments')
      .select('id, name, filter, created_at')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !data) {
      return NextResponse.json({ error: 'Segment not found' }, { status: 404 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, id }, 'segment fetch unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// DELETE — remove a saved segment
// ─────────────────────────────────────────────────────────────────────────────

export async function DELETE(_request: Request, context: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await context.params

  try {
    const supabase = await createClient()
    const client = makeAudienceSegmentsClient(supabase)

    const { error } = await client
      .from('audience_segments')
      .delete()
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.warn({ err: error, id }, 'segment delete failed')
      return NextResponse.json({ error: 'Could not delete segment' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'audience_segment.deleted',
      { type: 'audience_segment', id },
      null,
      authUser.studioId,
    )

    return NextResponse.json({ deleted: true })
  } catch (err) {
    logger.error({ err, id }, 'segment delete unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
