interface SuppressionRow {
  email: string
  reason: string
  created_at: string
}

// The email_suppression_list table is created by the M6 migration.
// Until pnpm db:types is re-run, cast to bypass the generated registry.
async function fetchSuppressionList(
  supabase: SupabaseClient,
  studioId: string,
): Promise<SuppressionRow[]> {
  const client = supabase as unknown as {
    from: (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          order: (col: string, opts: object) => {
            limit: (n: number) => Promise<{ data: SuppressionRow[] | null; error: { message: string } | null }>
          }
        }
      }
    }
  }
  const { data, error } = await client
    .from('email_suppression_list')
    .select('email, reason, created_at')
    .eq('studio_id', studioId)
    .order('created_at', { ascending: false })
    .limit(100)

  if (error) {
    logger.warn({ err: error, studioId }, 'hygiene list fetch failed — table may be pending migration')
    return []
  }
  return data ?? []
}

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const rows = await fetchSuppressionList(supabase, authUser.studioId)

    const bounces = rows.filter((r) => r.reason === 'bounce')
    const unsubs = rows.filter((r) => r.reason === 'unsubscribe')
    const complaints = rows.filter((r) => r.reason === 'complaint')

    return NextResponse.json({ data: { bounces, unsubs, complaints } })
  } catch (err) {
    logger.error({ err }, 'hygiene list unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
