export async function startWaitlistAutoPromoteListener(): Promise<void> {
  const dbUrl = workerEnv.SUPABASE_DB_URL
  if (!dbUrl) {
    logger.warn(
      'marketing-waitlist-auto-promote: SUPABASE_DB_URL not set — pg_notify listener disabled. ' +
      'Set SUPABASE_DB_URL (direct Postgres connection, not pooler) to enable auto-promote.',
    )
    return
  }

  const pgClient = new Client({ connectionString: dbUrl })
  await pgClient.connect()

  logger.info({ channel: CHANNEL }, 'marketing-waitlist-auto-promote: listening')

  await pgClient.query(`LISTEN "${CHANNEL}"`)

  pgClient.on('notification', (msg) => {
    if (msg.channel !== CHANNEL) return
    const bookingId = msg.payload?.trim()
    if (!bookingId) {
      logger.warn('marketing-waitlist-auto-promote: received empty payload, skipping')
      return
    }
    void processAutoPromote(bookingId).catch((err: unknown) => {
      logger.error({ err, bookingId }, 'marketing-waitlist-auto-promote: unhandled error')
    })
  })

  pgClient.on('error', (err) => {
    logger.error({ err }, 'marketing-waitlist-auto-promote: pg client error')
  })
}

