async function processAutoPromote(bookingId: string): Promise<void> {
  logger.info({ bookingId }, 'marketing-waitlist-auto-promote: processing')

  // 1. Load booking
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, studio_id, artist_id, service_id, start_at, status, cancelled_at')
    .eq('id', bookingId)
    .single()

  if (bookingErr || !booking) {
    logger.warn({ bookingId, err: bookingErr }, 'marketing-waitlist-auto-promote: booking not found')
    return
  }

  const b = booking as BookingRow

  if (b.status !== 'cancelled') {
    logger.info({ bookingId }, 'marketing-waitlist-auto-promote: booking not cancelled, skipping')
    return
  }

  // 2. Load studio auto-promote rules
  const { data: rules, error: rulesErr } = await supabase
    .from('marketing_waitlist_rules')
    .select('*')
    .eq('studio_id', b.studio_id)
    .maybeSingle()

  if (rulesErr) {
    logger.error({ err: rulesErr, studioId: b.studio_id }, 'marketing-waitlist-auto-promote: rules fetch failed')
    return
  }

  if (!rules) {
    logger.info({ studioId: b.studio_id }, 'marketing-waitlist-auto-promote: no rules configured, skipping')
    return
  }

  const r = rules as WaitlistRulesRow

  if (!r.auto_promote_on_cancel) {
    logger.info({ studioId: b.studio_id }, 'marketing-waitlist-auto-promote: auto-promote disabled, skipping')
    return
  }

  // 3. Check min_lead_time_hours
  const slotAt = new Date(b.start_at).getTime()
  const now = Date.now()
  const leadTimeMs = r.min_lead_time_hours * 60 * 60 * 1000

  if (slotAt - now < leadTimeMs) {
    logger.info(
      { bookingId, leadTimeHours: r.min_lead_time_hours },
      'marketing-waitlist-auto-promote: insufficient lead time, skipping',
    )
    return
  }

  // 4. Find first active waitlist entry matching studio + (artist or service)
  let waitlistQuery = supabase
    .from('waitlist_entries')
    .select('id, client_id, studio_id, artist_id, service_id, status')
    .eq('studio_id', b.studio_id)
    .eq('status', 'active')
    .order('created_at', { ascending: true })
    .limit(1)

  // Prefer matching on artist_id if available, fall back to service_id
  if (b.artist_id) {
    waitlistQuery = waitlistQuery.eq('artist_id', b.artist_id)
  } else if (b.service_id) {
    waitlistQuery = waitlistQuery.eq('service_id', b.service_id)
  }

  const { data: entries, error: entriesErr } = await waitlistQuery

  if (entriesErr) {
    logger.error({ err: entriesErr }, 'marketing-waitlist-auto-promote: waitlist query failed')
    return
  }

  if (!entries || entries.length === 0) {
    logger.info({ bookingId }, 'marketing-waitlist-auto-promote: no matching waitlist entries, skipping')
    return
