  if (clientEmail) {
    const { data: suppression } = await supabase
      .from('email_suppression_list')
      .select('email')
      .eq('studio_id', b.studio_id)
      .eq('email', clientEmail)
      .maybeSingle()

    if (suppression) {
      logger.info(
        { clientId: entry.client_id, email: clientEmail },
        'marketing-waitlist-auto-promote: client email suppressed, skipping',
      )
      return
    }
  }

  // 7. Enqueue the send with delay (auto_promote_window_minutes)
  const delayMs = r.auto_promote_window_minutes * 60 * 1000

  // Build slot description for template merge tag
  const slotDate = new Date(b.start_at).toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
