const PatchProgramSchema = z.object({
  referrer_reward_type: z
    .enum(['credit', 'percentage', 'free_session', 'none'])
    .nullable()
    .optional(),
  referrer_reward_value: z.number().nullable().optional(),
  referred_reward_type: z
    .enum(['discount_fixed', 'discount_percent', 'none'])
    .nullable()
    .optional(),
  referred_reward_value: z.number().nullable().optional(),
  trigger: z
    .enum(['booking_completed', 'first_booking', 'payment_settled'])
    .optional(),
  expiry_days: z.number().int().min(1).optional(),
  is_active: z.boolean().optional(),
})

/** Default program shape returned when no row exists yet. */
function defaultProgram(studioId: string) {
  return {
    studio_id: studioId,
    referrer_reward_type: null,
    referrer_reward_value: null,
    referred_reward_type: null,
    referred_reward_value: null,
    trigger: 'booking_completed' as const,
    expiry_days: 90,
    is_active: false,
    created_at: null,
    updated_at: null,
  }
}

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    const { data, error } = await supabase
      .from('referral_programs')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    if (error) {
