import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const BulkGenerateSchema = z.object({
  client_ids: z.array(z.string().uuid()).min(1).max(100),
})

/**
 * POST /api/marketing/referrals/codes/bulk
 *
 * Calls bulk_generate_referral_codes RPC (SECURITY DEFINER, audit-critical).
 * Rate-limited via expensiveRatelimit (heavier operation).
 */
export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await expensiveRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = BulkGenerateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  const { client_ids } = parsed.data
  const studioId = authUser.studioId

  try {
    // bulk_generate_referral_codes is SECURITY DEFINER — required per project rules.
    // Direct inserts are forbidden for audit-critical tables.
    const { data, error } = await supabase.rpc('bulk_generate_referral_codes', {
      p_studio_id: studioId,
      p_client_ids: client_ids,
    })

    if (error) {
      logger.error({ err: error, studioId }, 'bulk_generate_referral_codes RPC failed')

      // Surface specific errors from the RPC (no_program, program_inactive)
      if (error.message?.includes('no_program')) {
        return NextResponse.json(
          { error: 'No referral program configured. Set up your program first.' },
          { status: 422 },
        )
      }
      if (error.message?.includes('program_inactive')) {
        return NextResponse.json(
          { error: 'Referral program is inactive. Activate it in program settings.' },
          { status: 422 },
        )
      }

      return NextResponse.json({ error: 'Failed to generate referral codes' }, { status: 500 })
    }

    await logAuditAction(authUser.user.id, 'referral_codes.bulk_generated', null, { client_ids, count: client_ids.length }, studioId)

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'referral codes bulk generate unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

