import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { requirePersona } from '@/lib/auth/require-persona'
import { hasFeature } from '@/lib/billing/feature-gate'
import { CampaignsHub } from '@/components/marketing/CampaignsHub'
import { ReferralDashboard } from '@/components/marketing/ReferralDashboard'
import { AudienceTab } from './_components/AudienceTab'
import { WaitlistTab } from './_components/WaitlistTab'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { PageViews } from '@/components/shared/PageViews'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { CampaignDrawer } from '@/components/marketing/CampaignDrawer'
import { NewCampaignButton } from './_components/NewCampaignButton'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { CampaignType, CampaignStatus, CampaignChannel } from '@/lib/marketing/types'
import type { ReferralProgramData } from '@/components/marketing/ReferralProgramCard'

export const metadata: Metadata = {
  title: 'Marketing — InkOS',
}

const MARKETING_TABS: PageTab[] = [
  {
    key: 'audience',
    label: 'Audience',
    href: '/marketing?tab=audience',
  },
  {
    key: 'campaigns',
    label: 'Campaigns',
    href: '/marketing?tab=campaigns',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/marketing?tab=waitlist',
  },
  {
    key: 'referrals',
    label: 'Referral program',
    href: '/marketing?tab=referrals',
  },
]

const VALID_TABS = MARKETING_TABS.map((t) => t.key)

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function MarketingPage({ searchParams }: Props) {
  await requirePersona(['studio_owner'])
  const supabase = await createClient()

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, studio, role, plan } = activeStudio
  const planTier = plan as PlanTier
  const canManage = ['owner', 'admin'].includes(role)
  const hasMarketing = hasFeature(planTier, 'marketing_basic')
  const hasReferral = hasFeature(planTier, 'referral_program')

  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_TABS.includes(rawTab) ? rawTab : 'audience'

  // Only fetch data if the plan allows it
  let campaigns: Array<{
    id: string
    name: string
    type: CampaignType
    channel: CampaignChannel
    status: CampaignStatus
    sent_count: number
    open_count: number
    click_count: number
    scheduled_at: string | null
    sent_at: string | null
  }> = []

  let referralCodes: Array<{
    id: string
    code: string
    discount_type: 'percentage' | 'fixed'
    discount_value: number
    uses_count: number
    max_uses: number | null
    is_active: boolean
    expires_at: string | null
    client: { id: string; first_name: string; last_name: string; email: string } | null
  }> = []

  let clientOptions: Array<{ id: string; display: string }> = []
  let locationOptions: Array<{ id: string; name: string }> = []
  let initialProgram: ReferralProgramData | null = null
  let totalReferrals = 0
  let totalRedemptions = 0
  let topReferrers: Array<{ client_id: string; client_name: string; redemption_count: number }> = []

  if (hasMarketing) {
    const [campaignsResult, referralCodesResult, clientsResult, locationsResult, referralProgramResult, topReferrersResult] = await Promise.all([
      supabase
        .from('marketing_campaigns')
        .select('id, name, type, channel, status, sent_count, open_count, click_count, scheduled_at, sent_at')
        .eq('studio_id', studioId)
        .order('created_at', { ascending: false }),
      supabase
        .from('referral_codes')
        .select(`
          id, code, discount_type, discount_value, uses_count, max_uses, is_active, expires_at,
          client:clients(id, first_name, last_name, email)
        `)
        .eq('studio_id', studioId)
        .order('created_at', { ascending: false }),
      canManage
        ? supabase
            .from('clients')
            .select('id, first_name, last_name, email')
            .eq('studio_id', studioId)
            .is('archived_at', null)
            .order('first_name')
            .limit(200)
        : Promise.resolve({ data: [] as { id: string; first_name: string; last_name: string; email: string }[] }),
      supabase
        .from('locations')
        .select('id, name')
        .eq('studio_id', studioId)
        .eq('status', 'active')
        .order('name'),
      hasReferral
        ? supabase
            .from('referral_programs')
            .select('referrer_reward_type, referrer_reward_value, referred_reward_type, referred_reward_value, trigger, expiry_days, is_active')
            .eq('studio_id', studioId)
            .maybeSingle()
        : Promise.resolve({ data: null }),
      (async () => {
        const cutoff = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()
        return supabase
          .from('referral_redemptions')
          .select('referrer_client_id, client:clients!referral_redemptions_referrer_client_id_fkey(first_name, last_name)')
          .eq('studio_id', studioId)
          .gte('created_at', cutoff)
      })(),
    ])

    campaigns = (campaignsResult.data ?? []).map((c) => ({
      id: c.id,
      name: c.name,
      type: c.type as CampaignType,
      channel: c.channel as CampaignChannel,
      status: c.status as CampaignStatus,
      sent_count: c.sent_count,
      open_count: c.open_count,
      click_count: c.click_count,
      scheduled_at: c.scheduled_at,
      sent_at: c.sent_at,
    }))

    referralCodes = (referralCodesResult.data ?? []).map((c) => ({
      id: c.id,
      code: c.code,
      discount_type: c.discount_type as 'percentage' | 'fixed',
      discount_value: c.discount_value,
      uses_count: c.uses_count,
      max_uses: c.max_uses,
      is_active: c.is_active,
      expires_at: c.expires_at,
      client: c.client as { id: string; first_name: string; last_name: string; email: string } | null,
    }))

    clientOptions = (clientsResult.data ?? []).map((c) => ({
      id: c.id,
      display: `${c.first_name} ${c.last_name} (${c.email})`,
    }))

    locationOptions = (locationsResult.data ?? []).map((l) => ({ id: l.id, name: l.name }))

    totalReferrals = referralCodes.length
    totalRedemptions = referralCodes.reduce((sum, c) => sum + c.uses_count, 0)

    type RawRedemptionEntry = {
      referrer_client_id: string
      client: { first_name: string; last_name: string } | null
    }
    const redemptionRows = (topReferrersResult.data ?? []) as RawRedemptionEntry[]
    const referrerCounts = new Map<string, { name: string; count: number }>()
    for (const row of redemptionRows) {
      const id = row.referrer_client_id
      const c = row.client
      const name = c ? `${c.first_name} ${c.last_name}`.trim() : 'Unknown'
      const existing = referrerCounts.get(id)
      if (existing) { existing.count += 1 } else { referrerCounts.set(id, { name, count: 1 }) }
    }
    topReferrers = Array.from(referrerCounts.entries())
      .sort((a, b) => b[1].count - a[1].count)
      .slice(0, 5)
      .map(([client_id, { name, count }]) => ({
        client_id,
        client_name: name,
        redemption_count: count,
      }))

    const rawProgram = referralProgramResult.data
    if (rawProgram) {
      initialProgram = {
        referrer_reward_type: rawProgram.referrer_reward_type as ReferralProgramData['referrer_reward_type'],
        referrer_reward_value: rawProgram.referrer_reward_value,
        referred_reward_type: rawProgram.referred_reward_type as ReferralProgramData['referred_reward_type'],
        referred_reward_value: rawProgram.referred_reward_value,
        trigger: rawProgram.trigger as ReferralProgramData['trigger'],
        expiry_days: rawProgram.expiry_days,
        is_active: rawProgram.is_active,
      }
    }
  }

  return (
    <PageShell>
      <PageHeader
        title="Marketing"
        description="Reactivate, reward, never spam."
        {...(canManage && hasMarketing ? { actions: <NewCampaignButton /> } : {})}
      />

      <PageViews>
        <PageTabs
          tabs={filterTabsForRole(MARKETING_TABS, role as NavRole)}
          activeKey={activeKey}
          currentPlan={planTier}
          currentRole={role as NavRole}
        />
      </PageViews>

      <div role="tabpanel" id={`tabpanel-${activeKey}`}>
        {activeKey === 'audience' && (
          hasMarketing ? (
            <AudienceTab
              studioId={studioId}
              locationOptions={locationOptions}
            />
          ) : (
            <UpgradeGatePageBlock
              requiredPlan="studio"
              feature="Audience segments"
              description="Segment your clients by behaviour and spending to send targeted campaigns. Available on Studio plan and above."
            />
          )
        )}
        {activeKey === 'campaigns' && (
          hasMarketing ? (
            <CampaignsHub campaigns={campaigns} canManage={canManage} />
          ) : (
            <UpgradeGatePageBlock
              requiredPlan="studio"
              feature="Campaigns"
              description="Send email and SMS campaigns to your clients. Available on Studio plan and above."
            />
          )
        )}
        {activeKey === 'waitlist' && (
          hasMarketing ? (
            <WaitlistTab
              artistId={typeof params.w_artist === 'string' ? params.w_artist : undefined}
              serviceId={typeof params.w_service === 'string' ? params.w_service : undefined}
              eventId={typeof params.w_event === 'string' ? params.w_event : undefined}
              status={typeof params.w_status === 'string' ? (params.w_status as import('./_components/WaitlistFilterPills').WaitlistStatus) : undefined}
            />
          ) : (
            <UpgradeGatePageBlock
              requiredPlan="studio"
              feature="Waitlist management"
              description="Manage your waitlist and auto-promote clients when slots open. Available on Studio plan and above."
            />
          )
        )}
        {activeKey === 'referrals' && (
          hasReferral ? (
            <ReferralDashboard
              codes={referralCodes}
              totalReferrals={totalReferrals}
              totalRedemptions={totalRedemptions}
              topReferrers={topReferrers}
              clientOptions={clientOptions}
              canManage={canManage}
              initialProgram={initialProgram}
            />
          ) : (
            <UpgradeGatePageBlock
              requiredPlan="studio"
              feature="Referral program"
              description="Set up a referral program to reward clients who bring in new bookings. Available on Studio plan and above."
            />
          )
        )}
      </div>

      {/* CampaignDrawer mounts globally — opens on ?campaign=new from any tab */}
      {canManage && hasMarketing && (
        <CampaignDrawer
          studioId={studioId}
          studioTimezone={studio.timezone}
          studioName={studio.name}
          locationOptions={locationOptions}
        />
      )}
    </PageShell>
  )
}

